import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { Button } from '@shared/ui';
import { selectAuthUser } from 'core/store/auth-store';
import {
  selectAllShopCartProducts,
  selectShopCartTotal,
  removeProductFromCart,
  moveCartItemToWishlist,
  clearShoppingCart,
} from 'core/store/shop-cart';
import { selectWishlistIds } from 'core/store/wishlist';
import { enrollInFreeProductAPI } from 'core/api/services';
import {
  formatCommerceAmount,
  getCartCheckoutKind,
  getCommerceErrorMessage,
  isSuccessfulOrderStatus,
  isTerminalUnsuccessfulOrderStatus,
  startPaidCheckout,
  validatePaidCart,
} from './cart-checkout.utils';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './cart.styles.scss';

const Cart: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartProducts = useSelector(selectAllShopCartProducts);
  const cartTotal = useSelector(selectShopCartTotal);
  const wishlistIds = useSelector(selectWishlistIds);
  const [checkingOut, setCheckingOut] = useState(false);
  const cartCheckoutKind = getCartCheckoutKind(cartProducts);
  const containsPaidProducts = cartCheckoutKind === 'PAID';
  const containsMixedProducts = cartCheckoutKind === 'MIXED';

  const handleRemoveFromCart = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(removeProductFromCart(prod.id));
    }
  };

  const handleMoveToWishlist = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(moveCartItemToWishlist(prod.id));
    }
  };

  const handleFreeCheckout = async () => {
    const productIds = cartProducts
      .map((product) => product.id)
      .filter((id): id is string => Boolean(id));
    if (productIds.length === 0 || containsPaidProducts) {
      return;
    }

    setCheckingOut(true);
    try {
      await Promise.all(productIds.map(enrollInFreeProductAPI));
      dispatch(clearShoppingCart());
      toast.success('Products added to your library');
      navigate('/app/library/all-products');
    } catch {
      toast.error('The free products could not be added to your library.');
    } finally {
      setCheckingOut(false);
    }
  };

  const handlePaidCheckout = async () => {
    const validation = validatePaidCart(cartProducts, user?.id);
    if (!validation.valid) {
      toast.error(validation.message);
      return;
    }

    setCheckingOut(true);
    try {
      const { session, order } = await startPaidCheckout(cartProducts);

      if (session.checkoutUrl) {
        return;
      }

      if (!order) {
        toast.info('Checkout started. Your cart has been saved.');
        return;
      }

      const amount = formatCommerceAmount(order.totalMinor, order.currency);

      if (isSuccessfulOrderStatus(order.status)) {
        dispatch(clearShoppingCart());
        toast.success(
          amount
            ? `Payment confirmed for ${amount}. Products added to your library.`
            : 'Payment confirmed. Products added to your library.',
        );
        navigate('/app/library/all-products');
        return;
      }

      if (order.status === 'PENDING') {
        toast.info('Payment is still pending. Your cart has been saved.');
        return;
      }

      if (isTerminalUnsuccessfulOrderStatus(order.status)) {
        toast.error('Payment was not completed. Your cart has been saved.');
      }
    } catch (error) {
      toast.error(getCommerceErrorMessage(error));
    } finally {
      setCheckingOut(false);
    }
  };

  const handleCheckout = () => {
    if (containsMixedProducts) {
      toast.error(
        'Free and paid products cannot be checked out together. Please split your cart.',
      );
      return;
    }

    if (containsPaidProducts) {
      void handlePaidCheckout();
      return;
    }

    void handleFreeCheckout();
  };

  return (
    <div className="cart-page">
      <h1 className="cart-page-title">Shopping Cart</h1>
      {cartProducts.length > 0 ? (
        <>
          <section className="cart-container">
            <div className="cart-container-line">
              <p>{cartProducts.length} products in your cart</p>
              <hr className="cart-underline"></hr>
            </div>
            <article className="cart-products-container">
              <div className="cart-products-list">
                {cartProducts.map((prod) => {
                  const isInWishlist = wishlistIds.has(prod.id);
                  const productTitle = prod.title ?? 'Untitled product';

                  return (
                    <div key={prod.id} className="cart-product">
                      <img
                        src={placeholderImage}
                        alt={productTitle}
                        className="product-card-image"
                      />
                      <div className="cart-product-details">
                        <h3>{productTitle}</h3>
                        <p>By {prod.createdByName}</p>
                        <p>4.7 ⭐⭐⭐⭐⭐ (32,025 ratings)</p>
                      </div>
                      <div className="cart-product-actions">
                        <button
                          type="button"
                          onClick={() => handleRemoveFromCart(prod)}
                        >
                          Remove
                        </button>
                        <button
                          type="button"
                          disabled={isInWishlist}
                          onClick={() => handleMoveToWishlist(prod)}
                        >
                          Move to wishlist
                        </button>
                      </div>
                      <div className="cart-product-price-tag">
                        €{prod.price}
                      </div>
                    </div>
                  );
                })}
              </div>
            </article>
            <aside className="cart-products-aside">
              <h4>Total:</h4>
              <h2>
                {cartTotal && cartTotal > 0 ? (
                  <span>€{cartTotal}</span>
                ) : (
                  <span>free</span>
                )}
              </h2>
              {containsPaidProducts && (
                <p className="cart-products-aside__notice" role="note">
                  Test payment — No real charge will be made during checkout.
                </p>
              )}

              <Button
                type="button"
                variant="primary"
                disabled={checkingOut}
                onClick={handleCheckout}
              >
                {checkingOut ? 'Processing...' : 'Proceed to checkout'}
              </Button>
              {containsMixedProducts && (
                <p role="alert" className="cart-products-aside__message">
                  Free and paid products cannot be checked out together. Please
                  split your cart.
                </p>
              )}
            </aside>
          </section>
        </>
      ) : (
        <p>You don&apos;t have any products in your shopping cart</p>
      )}
      <div className="cart-page-bottom">
        <h2>You might also like</h2>
      </div>
    </div>
  );
};

export default Cart;

import { AxiosError } from 'axios';

import {
  CommerceCheckoutSession,
  CommerceOrder,
  CommerceOrderStatus,
  ProductMinimised,
} from 'core/api/models';
import {
  createCommerceCheckoutSessionAPI,
  getCommerceOrderAPI,
} from 'core/api/services';

const IDEMPOTENCY_STORAGE_KEY = 'commerceCheckout:idempotency:v1';
const IDEMPOTENCY_TTL_MS = 30 * 60 * 1000;
const MAX_CHECKOUT_PRODUCTS = 20;

interface StoredIdempotency {
  cartSignature: string;
  key: string;
  createdAt: number;
}

export type CartCheckoutKind = 'FREE' | 'PAID' | 'MIXED' | 'EMPTY';

export interface CartValidationResult {
  valid: boolean;
  message?: string;
}

export interface PaidCheckoutResult {
  session: CommerceCheckoutSession;
  order?: CommerceOrder;
}

export const getProductPriceAmount = (product: ProductMinimised): number => {
  if (product.price === 'free' || product.price === null || product.price === undefined) {
    return 0;
  }

  return Number(product.price) || 0;
};

export const getCartCheckoutKind = (
  products: ProductMinimised[],
): CartCheckoutKind => {
  if (products.length === 0) {
    return 'EMPTY';
  }

  const freeCount = products.filter(
    (product) => getProductPriceAmount(product) === 0,
  ).length;

  if (freeCount === products.length) {
    return 'FREE';
  }

  if (freeCount === 0) {
    return 'PAID';
  }

  return 'MIXED';
};

export const formatCommerceAmount = (
  totalMinor?: number,
  currency = 'EUR',
): string | null => {
  if (typeof totalMinor !== 'number') {
    return null;
  }

  return new Intl.NumberFormat(undefined, {
    style: 'currency',
    currency,
  }).format(totalMinor / 100);
};

export const validatePaidCart = (
  products: ProductMinimised[],
  buyerId?: string,
): CartValidationResult => {
  if (products.length === 0) {
    return { valid: false, message: 'Your cart is empty.' };
  }

  if (products.length > MAX_CHECKOUT_PRODUCTS) {
    return {
      valid: false,
      message: 'Checkout supports up to 20 products at a time.',
    };
  }

  if (getCartCheckoutKind(products) === 'MIXED') {
    return {
      valid: false,
      message:
        'Free and paid products cannot be checked out together. Please split your cart.',
    };
  }

  if (products.some((product) => getProductPriceAmount(product) === 0)) {
    return {
      valid: false,
      message: 'Free products use free enrollment and cannot enter paid checkout.',
    };
  }

  if (products.some((product) => product.type === 'MEMBERSHIP')) {
    return {
      valid: false,
      message: 'Membership checkout is not available yet.',
    };
  }

  const productIds = products
    .map((product) => product.id)
    .filter((id): id is string => Boolean(id));

  if (productIds.length !== products.length) {
    return {
      valid: false,
      message: 'One or more cart products cannot be checked out yet.',
    };
  }

  if (new Set(productIds).size !== productIds.length) {
    return {
      valid: false,
      message: 'Duplicate products cannot be checked out together.',
    };
  }

  const creatorIds = products
    .map((product) => product.createdById)
    .filter((id): id is string => Boolean(id));

  if (creatorIds.length === products.length && new Set(creatorIds).size > 1) {
    return {
      valid: false,
      message: 'Products from different Creators cannot be checked out together.',
    };
  }

  if (
    buyerId &&
    products.some((product) => product.createdById && product.createdById === buyerId)
  ) {
    return {
      valid: false,
      message: 'You cannot buy your own product.',
    };
  }

  if (
    products.some(
      (product) => product.status && product.status !== 'PUBLISHED',
    )
  ) {
    return {
      valid: false,
      message: 'Only published products can be checked out.',
    };
  }

  return { valid: true };
};

export const getPaidProductIds = (products: ProductMinimised[]): string[] =>
  products
    .filter((product) => getProductPriceAmount(product) > 0)
    .map((product) => product.id)
    .filter((id): id is string => Boolean(id));

export const getCartSignature = (productIds: string[]): string =>
  [...productIds].sort().join('|');

const readStoredIdempotency = (): StoredIdempotency | null => {
  try {
    if (typeof window === 'undefined') {
      return null;
    }

    const raw = window.sessionStorage.getItem(IDEMPOTENCY_STORAGE_KEY);
    return raw ? (JSON.parse(raw) as StoredIdempotency) : null;
  } catch {
    return null;
  }
};

const writeStoredIdempotency = (entry: StoredIdempotency) => {
  try {
    if (typeof window === 'undefined') {
      return;
    }

    window.sessionStorage.setItem(
      IDEMPOTENCY_STORAGE_KEY,
      JSON.stringify(entry),
    );
  } catch {
    /* ignore storage errors */
  }
};

export const getIdempotencyKeyForCart = (
  productIds: string[],
  now = Date.now(),
): string => {
  const cartSignature = getCartSignature(productIds);
  const existing = readStoredIdempotency();

  if (
    existing?.cartSignature === cartSignature &&
    now - existing.createdAt < IDEMPOTENCY_TTL_MS
  ) {
    return existing.key;
  }

  const key = crypto.randomUUID();
  writeStoredIdempotency({ cartSignature, key, createdAt: now });

  return key;
};

export const getCommerceErrorMessage = (error: unknown): string => {
  const status = (error as AxiosError)?.response?.status;

  switch (status) {
  case 400:
    return 'Checkout could not start. Please try again.';
  case 409:
    return 'Checkout could not continue because this cart changed or includes a product you already own.';
  case 422:
    return 'This cart cannot be checked out. Please review the products and try again.';
  case 503:
    return 'Payments are not configured right now. Please try again later.';
  default:
    return 'Checkout could not be started. Please try again.';
  }
};

export const isSuccessfulOrderStatus = (status: CommerceOrderStatus) =>
  status === 'PAID';

export const isTerminalUnsuccessfulOrderStatus = (
  status: CommerceOrderStatus,
) => status === 'FAILED' || status === 'EXPIRED' || status === 'REFUNDED';

export const startPaidCheckout = async (
  products: ProductMinimised[],
): Promise<PaidCheckoutResult> => {
  const productIds = getPaidProductIds(products);
  const idempotencyKey = getIdempotencyKeyForCart(productIds);
  const session = await createCommerceCheckoutSessionAPI(
    productIds,
    idempotencyKey,
  );

  if (session.checkoutUrl) {
    window.location.assign(session.checkoutUrl);
    return { session };
  }

  if (!session.orderId) {
    return { session };
  }

  const order = await getCommerceOrderAPI(session.orderId);
  return { session, order };
};

import httpClient from 'core/api/http-client';
import { CommerceCheckoutSession, CommerceOrder } from 'core/api/models';

export const createCommerceCheckoutSessionAPI = async (
  productIds: string[],
  idempotencyKey: string,
): Promise<CommerceCheckoutSession> => {
  const response = await httpClient.post<CommerceCheckoutSession>(
    'api/commerce/checkout-sessions',
    { productIds },
    {
      headers: {
        'Idempotency-Key': idempotencyKey,
      },
      withCredentials: true,
    },
  );

  return response.data;
};

export const getCommerceOrderAPI = async (
  orderId: string,
): Promise<CommerceOrder> => {
  const response = await httpClient.get<CommerceOrder>(
    `api/commerce/orders/${orderId}`,
    { withCredentials: true },
  );

  return response.data;
};

