import {
  AnyAction,
  createSlice,
  PayloadAction,
  ThunkAction,
} from '@reduxjs/toolkit';

import { ProductMinimised, RootState } from 'core/api/models';
import { addToWishlist } from '../wishlist/wishlist.slice';

const STORAGE_KEY = 'cart:v1';

export interface ShopCartState {
  products: ProductMinimised[];
  loading: boolean;
  total: number;
}

const initialState: ShopCartState = {
  products: [],
  loading: false,
  total: 0,
};

export const loadCartFromStorage = (): ShopCartState | undefined => {
  try {
    if (typeof window === 'undefined') {
      return undefined;
    }
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as ShopCartState) : undefined;
  } catch {
    return undefined;
  }
};

export const saveCartToStorage = (state: ShopCartState) => {
  try {
    if (typeof window === 'undefined') {
      return;
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    /* ignore quota / privacy errors */
  }
};

const getNumericPrice = (p: ProductMinimised): number => {
  const price = p.price;
  if (price === 'free' || price === null) {
    return 0;
  }
  return typeof price === 'number' ? price : Number(price) || 0;
};

const recomputeTotal = (items: ProductMinimised[]) =>
  items.reduce((sum, p) => sum + getNumericPrice(p), 0);

export const moveCartItemToWishlist =
  (productId: string): ThunkAction<void, RootState, unknown, AnyAction> =>
  (dispatch, getState) => {
    const state = getState();

    // find the product in wishlist
    const product = state.shopCart.products.find((p) => p.id === productId);
    if (!product) {
      return;
    } // nothing to do

    // if already in cart, just remove from wishlist (optional behavior)
    const isAlreadyInWishlist = state.wishlist.products.some(
      (p) => p.id === productId,
    );

    if (!isAlreadyInWishlist) {
      dispatch(addToWishlist(product));
    }
    dispatch(removeProductFromCart(productId));
  };

const shopCartSlice = createSlice({
  name: 'shopCart',
  initialState,
  reducers: {
    addProductToCart(state, action: PayloadAction<ProductMinimised>) {
      state.loading = true;

      // optional: prevent duplicates (by product id)
      const exists = state.products?.some((p) => p.id === action.payload.id);
      if (!exists) {
        state.products?.push(action.payload);
      }

      state.total = recomputeTotal(state.products);
      state.loading = false;
    },

    removeProductFromCart(
      state,
      action: PayloadAction<string /* productId */>,
    ) {
      const idToRemove = action.payload;
      const idx = state.products?.findIndex((p) => p.id === idToRemove);
      if (idx >= 0) {
        state.products?.splice(idx, 1);
        state.total = recomputeTotal(state.products);
      }
      state.loading = false;
    },

    clearShoppingCart(state) {
      state.products = [];
      state.total = 0;
      state.loading = false;
    },
  },
});

export const { addProductToCart, clearShoppingCart, removeProductFromCart } =
  shopCartSlice.actions;
export default shopCartSlice.reducer;

import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { FaRegHeart } from 'react-icons/fa';
import { FaHeart } from 'react-icons/fa';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { getAllProductsMinimalAPI } from 'core/api/services';
import { Icon, Button } from '@shared/ui';
import { appRoutes } from '../../routes/routes';
import {
  selectAllShopCartProducts,
  addProductToCart,
} from 'core/store/shop-cart';
import { selectWishlistIds, toggleWishlist } from 'core/store/wishlist';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../assets/image-placeholder.png');

import './explore-page.styles.scss';

const ExplorePage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch<AppDispatch>();
  const cartProducts = useSelector(selectAllShopCartProducts);
  const wishlistIds = useSelector(selectWishlistIds);
  const [products, setProducts] = useState<ProductMinimised[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true; // ↪️ prevent state updates after unmount

    // call your service
    getAllProductsMinimalAPI()
      .then((data) => {
        if (isMounted) {
          setProducts(data);
        }
      })
      .catch((err) => {
        console.error(err);
        if (isMounted) {
          setError('Failed to load products.');
        }
      })
      .finally(() => {
        if (isMounted) {
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, []); // empty deps → runs once on mount

  const handleAddToCart = (prod: ProductMinimised) => {
    dispatch(addProductToCart(prod));
  };

  const handleToggleWishlist = (prod: ProductMinimised) => {
    dispatch(toggleWishlist(prod));
  };

  const isInCart = (productId: string | undefined) =>
    cartProducts?.some((p) => p.id === productId);

  if (loading) {
    return <p>Loading products…</p>;
  }
  if (error) {
    return <p>{error}</p>;
  }
  return (
    <div className="explore-page">
      <main className="explore-page-content">
        <section className="intro">
          <h1>Check this out</h1>
          <p>
            Here we show products. This is where people search for products or
            instructors
          </p>
          <p>
            All types of users have access to this page, even visitors (people
            without an account)
          </p>
          <p>
            All types of registered users (User, Creator, Admin) have a quick
            access link to this page
          </p>
        </section>
        <section className="explore-products">
          <h1>These are our best products</h1>
          <div className="products-list">
            {products?.map((product, idx) => {
              const wished = wishlistIds.has(product.id);
              const productName = product.title ?? 'Untitled product';

              return (
                <div key={idx} className="product-card">
                  <img
                    src={placeholderImage}
                    alt={productName}
                    className="product-card-image"
                  />

                  <button
                    type="button"
                    className={`wish-btn ${wished ? 'is-active' : ''}`}
                    aria-pressed={wished}
                    aria-label={
                      wished ? 'Remove from wishlist' : 'Add to wishlist'
                    }
                    onClick={() => handleToggleWishlist(product)}
                    title={wished ? 'Remove from wishlist' : 'Add to wishlist'}
                  >
                    {wished ? (
                      <Icon icon={FaHeart} size={22} color="red" />
                    ) : (
                      <Icon icon={FaRegHeart} size={22} />
                    )}
                  </button>
                  <div className="product-card-details">
                    <div className="last-updated-line">
                      <span>
                        {product.updatedAt &&
                          new Date(product.updatedAt).toLocaleDateString(
                            'en-GB',
                            {
                              day: 'numeric',
                              month: 'long',
                              year: 'numeric',
                            },
                          )}
                      </span>
                    </div>
                    <h3>{productName}</h3>
                    <div className="type-and-price-line">
                      <span>{product.type?.toLowerCase()}</span>
                      <span>
                        {product.price !== 'free' && <span>&euro;</span>}
                        {product.price}
                      </span>
                    </div>
                    <button
                      type="button"
                      className="creator-route-btn"
                      onClick={() => navigate(`/store/${product.createdById}`)}
                    >
                      <span className="creator">
                        {product.createdByName}, {product.createdByTitle}
                      </span>
                    </button>
                  </div>
                  <div className="explore-card-actions">
                    <Button
                      type="button"
                      variant="secondary"
                      onClick={() =>
                        navigate(appRoutes.product(product.id, product.type))
                      }
                    >
                      View Product
                    </Button>
                    <Button
                      type="button"
                      variant="primary"
                      disabled={isInCart(product.id)}
                      onClick={() => {
                        if (!isInCart(product.id)) {
                          handleAddToCart(product);
                        }
                      }}
                    >
                      {isInCart(product.id) ? 'Already in cart' : 'Add to cart'}
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      </main>
    </div>
  );
};

export default ExplorePage;

